import {COLORS,category,localTime} from './core.js';
import {QUICK,defaults,filterRows,cuisineCounts,sourceDate,statusText,sortRows,compareToggle,readSaved} from './discovery.js';
import {RestaurantMap} from './map.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeUrl=s=>{try{const u=new URL(s);return['http:','https:'].includes(u.protocol)?u.href:'#'}catch{return'#'}};
const link=(href,text,cls='')=>`<a class="${cls}" href="${esc(safeUrl(href))}" target="_blank" rel="noopener">${esc(text)} ↗</a>`;
const mapsUrl=r=>'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(r.name+' '+r.address);
const time=n=>n===1440?'midnight':`${Math.floor(n/60)%12||12}${n%60?':'+String(n%60).padStart(2,'0'):''}${n<720?'am':'pm'}`;
const schedule=h=>h===null||h===undefined?'Unknown':h.length?h.map(([a,b])=>time(a)+'–'+time(b)+(b<a?' next day':'')).join(', '):'Closed';
const today=r=>r.status==='closed'?'Permanently closed':r.status==='temporarily_closed'?'Temporarily closed':r.status==='needs_review'?'Needs review':r.hours?schedule(r.hours[localTime().day]):'Hours unconfirmed';
let bundle,restaurants=[],visible=[],filters=defaults(),saved;try{saved=readSaved(localStorage)}catch{saved=new Set()}
let compareIds=[],selected=null,lastFocus=null,carouselIndex=0,toastTimer,searchTimer,carouselTimer;
const cityMap=new RestaurantMap(showDetail);
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,3500);}
function photos(r){if(r.photos?.length)return r.photos;const p=[];if(r.foodPhoto)p.push({url:r.foodPhoto,alt:'Food at '+r.name,source:r.website,credit:r.name});if(r.photo)p.push({url:r.photo,alt:r.name+' exterior',source:r.photoSource||r.website,credit:r.photoCredit||r.name});return p;}
function photo(r,cls='card-photo'){const p=photos(r)[0];return p?`<img class="${cls}" src="${esc(safeUrl(p.url))}" alt="${esc(p.alt||r.name)}" loading="lazy" referrerpolicy="no-referrer">`:`<span class="${cls} photo-placeholder" style="--c:${COLORS[category(r.cuisine)]}"><b>${category(r.cuisine)==='Café & bakery'?'☕':'◒'}</b><small>Photo pending</small></span>`;}
function imageFallbacks(root=document){root.querySelectorAll('img').forEach(img=>{img.onerror=()=>{const f=document.createElement('span');f.className=img.className+' photo-placeholder';f.textContent='Photo unavailable';img.replaceWith(f);};});}
function card(r,mobile=false){
 const status=statusText(r),flag=['closed','temporarily_closed','needs_review'].includes(r.status);
 if(mobile)return`<button class="mobile-card" data-open="${r.id}" data-id="${r.id}" aria-label="View ${esc(r.name)}">${photo(r)}<span><strong>${esc(r.name)}</strong><small>${esc(r.cuisine)} · ${esc(r.priceLabel||'Price unknown')}</small><small class="${flag?'review-text':''}">${esc(status)}</small></span></button>`;
 return`<article class="restaurant-card ${selected===r.id?'selected':''}" data-id="${r.id}" data-category="${category(r.cuisine)}"><button class="card-main" data-open="${r.id}" aria-label="View ${esc(r.name)}">${photo(r)}<span class="card-info"><h3>${esc(r.name)}</h3><span>${esc(r.cuisine)} · ${esc(r.priceLabel||'Price unknown')}</span><small>${esc(r.district||r.neighborhood)}</small>${r.rating?`<small><span class="star">★ ${r.rating.value.toFixed(1)}</span> ${esc(r.rating.provider)}</small>`:'<small>Rating unconfirmed</small>'}</span></button><div class="card-status ${flag?'review-text':''}">${esc(status)}</div>${r.dishes?.length?`<p class="card-dishes">${esc(r.dishes.slice(0,2).join(' · '))}</p>`:''}<div class="card-actions"><button data-save="${r.id}" aria-pressed="${saved.has(r.id)}" aria-label="${saved.has(r.id)?'Unsave':'Save'} ${esc(r.name)}">${saved.has(r.id)?'♥ Saved':'♡ Save'}</button><button data-compare="${r.id}" aria-pressed="${compareIds.includes(r.id)}" aria-label="${compareIds.includes(r.id)?'Remove':'Add'} ${esc(r.name)} ${compareIds.includes(r.id)?'from':'to'} comparison">${compareIds.includes(r.id)?'✓ Compare':'+ Compare'}</button>${link(mapsUrl(r),'Directions')}</div></article>`;
}
function filterLabels(){return [['query',filters.query?`Search: ${filters.query}`:''],['cuisine',filters.cuisine],['quick',QUICK[filters.quick]],['district',filters.district],['price',filters.price?({'1':'$ · Budget',mid:'$$–$$$','4':'$$$$'})[filters.price]:''],['rating',filters.rating?`${filters.rating}+ stars`:''],['open',filters.open?'Open now':''],['includeClosed',filters.includeClosed?'Historical places included':''],['favorites',filters.favorites?'Saved places':'']].filter(([,label])=>label);}
function syncControls(){
 $('#search').value=filters.query;$('#clear-search').hidden=!filters.query;$('#local-area').value=filters.district;$('#price').value=filters.price;$('#rating').value=String(filters.rating);$('#open-now').checked=filters.open;$('#include-closed').checked=filters.includeClosed;$('#favorites-filter').setAttribute('aria-pressed',String(filters.favorites));$('#saved-count').textContent=saved.size;$$('[data-area]').forEach(b=>b.classList.toggle('active',b.dataset.area===filters.district));
 const counts=cuisineCounts(restaurants,filters,saved);
 $('#cuisines').innerHTML=['',...Object.keys(COLORS)].map(c=>`<button class="cuisine-chip ${filters.cuisine===c?'active':''}" data-cuisine="${esc(c)}" aria-pressed="${filters.cuisine===c}" aria-label="${c||'All cuisines'}, ${counts[c]} matches">${c?`<i style="--c:${COLORS[c]}"></i>`:'✦'}<span>${c==='Café & bakery'?'Cafés & bakery':c||'All cuisines'}</span><b>${counts[c]}</b></button>`).join('');
 $('#quick-filters').innerHTML=Object.entries(QUICK).map(([key,label])=>`<button data-quick="${key}" aria-pressed="${filters.quick===key}" class="${filters.quick===key?'active':''}">${label}</button>`).join('');const labels=filterLabels();$('#filter-count').textContent=labels.length?`(${labels.length})`:'';$('#active-filters').innerHTML=labels.map(([key,label])=>`<button data-remove="${key}" aria-label="Remove ${esc(label)} filter">${esc(label)} <span>×</span></button>`).join('');
}
function explanation(){let t=visible.length?`${visible.length} matching places shown on both the list and map.`:'No matches. Remove a filter or reset to see more places.';if(!filters.includeClosed)t+=' Permanently closed places hidden.';if(filters.rating)t+=' Unrated places excluded; ratings are provider snapshots.';if(filters.price)t+=' Places without price information excluded.';if(filters.open)t+=' Unknown hours and unresolved listings excluded. Holiday changes may differ.';if(filters.quick==='open-late')t+=' Published hours reach 10 pm or later today; kitchen hours may differ.';if(filters.quick==='date-night')t+=' Editorial picks with linked dining and drinks evidence.';if(filters.quick==='takeout')t+=' Only places with a checked takeout or ordering source.';if(filters.favorites&&!saved.size)t='No saved places yet. Tap Save on a restaurant card to start your list.';return t;}
function render({fly=false,updateMap=true}={}){
 visible=sortRows(filterRows(restaurants,filters,saved),$('#sort').value);syncControls();$('#count').textContent=visible.length;$('#filter-explanation').textContent=explanation();$('#results').innerHTML=visible.length?visible.map(r=>card(r)).join(''):`<div class="empty"><h3>${filters.favorites?'Your saved list is empty':'No matching places'}</h3><p>${esc(explanation())}</p><button data-reset>Reset all filters</button></div>`;
 $('#map-title').textContent=filters.district?filters.district.split(' & ')[0]:filters.cuisine||QUICK[filters.quick]||(filters.favorites?'Saved places':'All Nashua');$('#map-results').textContent=`${visible.length} matching places${filterLabels().length?' · filters applied':''}`;$('#coverage').textContent=`${restaurants.length} records · incomplete directory`;$('#mobile-cards').innerHTML=visible.length?visible.map(r=>card(r,true)).join(''):'<div class="mobile-empty">No matches. Open Filters to reset.</div>';carouselIndex=0;$('#mobile-cards').scrollLeft=0;updateCarouselCounter();if(selected&&!visible.some(r=>r.id===selected))closeDetail(false);if(updateMap)cityMap.update(visible,filters.cuisine);if(fly){if(!filterLabels().length)cityMap.fitCity();else cityMap.fit(visible);}updateCompareBar();imageFallbacks();
}
function applyFilter(key,value){filters[key]=value;render({fly:true});}
function reset(){clearTimeout(searchTimer);$('#sort').value='featured';filters=defaults();closeDetail(false);render({fly:true});}
function setView(view){document.body.dataset.view=view;$('#map-view').setAttribute('aria-pressed',String(view==='map'));$('#list-view').setAttribute('aria-pressed',String(view==='list'));requestAnimationFrame(()=>cityMap.resize());}
function updateCarouselCounter(){$('#carousel-count').textContent=visible.length?`${carouselIndex+1} / ${visible.length} places · swipe to browse`:'0 matching places';$('#previous-place').disabled=carouselIndex<=0;$('#next-place').disabled=carouselIndex>=visible.length-1;}
function moveCarousel(delta){const i=Math.max(0,Math.min(visible.length-1,carouselIndex+delta));$('#mobile-cards').children[i]?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'nearest',inline:'center'});}
function save(id){saved.has(id)?saved.delete(id):saved.add(id);try{localStorage.setItem('nashua-table-favorites',JSON.stringify([...saved]));}catch{toast('Saved for this visit. Browser storage is unavailable.');}render({updateMap:filters.favorites});if(selected)renderDetail(restaurants.find(r=>r.id===selected));}
function compare(id){const next=compareToggle(compareIds,id);if(next===compareIds){toast('Compare up to three places. Remove one to add another.');return;}compareIds=next;render({updateMap:false});if(selected)renderDetail(restaurants.find(r=>r.id===selected));if($('#compare-dialog').open)renderComparison();}
function updateCompareBar(){$('#compare-bar').hidden=!compareIds.length;$('#compare-count').textContent=`${compareIds.length} of 3 selected`;document.body.classList.toggle('has-comparison',!!compareIds.length);}
function freshness(r,field){const date=sourceDate(r,field);return date?`Source checked ${date}`:'Source check date unavailable';}
function renderDetail(r){
 const gallery=photos(r),days=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
 $('#detail').innerHTML=`<button class="detail-close" aria-label="Close restaurant details">×</button><div class="detail-gallery">${gallery.length?gallery.map(p=>`<figure><img src="${esc(safeUrl(p.url))}" alt="${esc(p.alt||r.name)}" loading="lazy" referrerpolicy="no-referrer"><figcaption>${link(p.source||r.website,p.credit||r.name)}</figcaption></figure>`).join(''):`<div class="detail-placeholder">${category(r.cuisine)==='Café & bakery'?'☕':'◒'}<small>Venue photo not yet verified</small></div>`}</div><div class="detail-body"><div class="eyebrow">${esc(r.district||r.neighborhood)}</div><h2>${esc(r.name)}</h2><div class="detail-meta">${esc(r.cuisine)} · ${esc(r.priceLabel||'Price unconfirmed')}</div><span class="badge ${['closed','temporarily_closed','needs_review'].includes(r.status)?'closed':''}">${esc(statusText(r))}</span><p class="today-hours">Today: ${esc(today(r))}</p><div class="visit-actions">${r.phone?`<a class="primary" href="tel:${esc(r.phone.replace(/[^+0-9]/g,''))}">Call</a>`:'<span class="unavailable-action">Phone unconfirmed</span>'}${link(mapsUrl(r),'Directions','primary')}${r.menuUrl?link(r.menuUrl,'View menu','secondary'):r.website?link(r.website,'Website & menu','secondary'):'<span>Menu link unconfirmed</span>'}</div><div class="detail-tools"><button data-save="${r.id}" aria-pressed="${saved.has(r.id)}">${saved.has(r.id)?'♥ Saved':'♡ Save'}</button><button data-compare="${r.id}" aria-pressed="${compareIds.includes(r.id)}">${compareIds.includes(r.id)?'✓ Comparing':'+ Compare'}</button><button data-share="${r.id}">Share ↗</button></div>${r.notes?`<p class="source-note">${esc(r.notes)}</p>`:''}${r.description?`<p>${esc(r.description)}</p>`:''}<h3>Menu highlights</h3>${r.dishes?.length?`<div class="dishes">${r.dishes.map(d=>`<button class="dish" data-dish="${esc(d)}">${esc(d)}</button>`).join('')}</div><p class="field-date">${freshness(r,'dishes')}. Availability may change.</p>`:'<p>Menu highlights not yet verified. Use the venue menu link.</p>'}${r.rating?`<h3><span class="star">★ ${r.rating.value.toFixed(1)}</span> / 5 · ${link(r.rating.url,r.rating.provider)}</h3><p class="field-date">${freshness(r,'rating')}. Snapshot, not a live rating.</p>`:'<p>Rating not yet verified</p>'}<div class="info-row"><strong>ADDRESS</strong>${link(mapsUrl(r),r.address)}<small>${esc(r.precision)}. Shared-site pins are spread for selection; use the address for directions.</small></div><div class="info-row"><strong>PHONE</strong>${esc(r.phone||'Not yet verified')}<small>${freshness(r,'phone')}</small></div><div class="info-row"><strong>HOURS · EASTERN TIME</strong>${['closed','temporarily_closed','needs_review'].includes(r.status)?esc(statusText(r)):r.hours?`<table class="hours">${r.hours.map((h,i)=>`<tr class="${localTime().day===i?'today':''}"><th>${days[i]}</th><td>${schedule(h)}</td></tr>`).join('')}</table>`:'Weekly hours not yet verified.'}<small>${freshness(r,'hours')}${r.hoursSource?' · '+esc(r.hoursSource):''}. Holiday hours may differ.</small></div>${r.status!=='closed'?link(`https://www.google.com/maps/@?api=1&map_action=pano&viewpoint=${r.lat},${r.lng}`,'Street View / step inside','secondary'):'<p>Historical location; permanently closed.</p>'}<p class="field-date">Street View opens nearby panoramas. Interior coverage varies.</p>${r.discovery?.['date-night']?`<h3>Why it’s a date-night pick</h3><p>${esc(r.discovery['date-night'].reason)} ${link(r.discovery['date-night'].source,'Source')}</p><p class="field-date">Editorial selection, not a rating.</p>`:''}<details class="source-details"><summary>Sources & field check dates</summary><p>Dates indicate when a source was checked, not confirmation of current service.</p>${r.sources.map(s=>`<div>${link(s.url,s.label)}<small>${esc((s.fields||[]).join(', '))} · ${esc(s.checkedAt||'Check date unavailable')}</small></div>`).join('')}<p>Price: ${freshness(r,'price')}</p><p>Record compiled ${esc(r.checkedAt||bundle.compiledAt)}.</p></details><h3>Compare external listings</h3><div class="source-links">${link(mapsUrl(r),'Google Maps')}${link('https://www.yelp.com/search?find_desc='+encodeURIComponent(r.name)+'&find_loc=Nashua%2C+NH','Yelp')}${link('https://www.tripadvisor.com/Search?q='+encodeURIComponent(r.name+' Nashua'),'Tripadvisor')}</div><p class="field-date">Search links are lookup shortcuts, not verified profiles.</p></div>`;
 $('#detail .detail-close').onclick=()=>closeDetail();imageFallbacks($('#detail'));
}
function showDetail(id){const r=restaurants.find(r=>r.id===id);if(!r)return;lastFocus=document.activeElement;selected=id;if(innerWidth<=760)setView('map');renderDetail(r);$('#detail').hidden=false;$('#detail').scrollTop=0;document.body.classList.add('detail-open');$$('.restaurant-card').forEach(c=>c.classList.toggle('selected',c.dataset.id===id));cityMap.focus(r);$('#detail .detail-close').focus({preventScroll:true});const u=new URL(location.href);u.searchParams.set('place',id);history.replaceState(null,'',u);}
function closeDetail(restore=true){selected=null;cityMap.selected=null;$('#detail').hidden=true;document.body.classList.remove('detail-open');const u=new URL(location.href);u.searchParams.delete('place');history.replaceState(null,'',u);$$('.restaurant-card.selected').forEach(c=>c.classList.remove('selected'));if(restore&&lastFocus?.isConnected)lastFocus.focus({preventScroll:true});}
function renderComparison(){
 const rows=compareIds.map(id=>restaurants.find(r=>r.id===id)).filter(Boolean);if(!rows.length){$('#comparison').innerHTML='<p>No places selected. Add up to three using Compare on any restaurant card.</p>';return;}
 const columns=[['Cuisine',r=>esc(r.cuisine)],['Price',r=>esc(r.priceLabel||'Unknown')],['Rating',r=>r.rating?`${r.rating.value.toFixed(1)} · ${esc(r.rating.provider)}<small>${esc(r.rating.capturedAt||'Check date unknown')}</small>`:'Unverified'],['Status',r=>esc(statusText(r))],['Hours today',r=>esc(today(r))],['Menu highlights',r=>esc(r.dishes?.join(' · ')||'Not verified')],['Address',r=>link(mapsUrl(r),r.address)],['Menu',r=>r.menuUrl?link(r.menuUrl,'Menu'):r.website?link(r.website,'Website & menu'):'Unconfirmed']];
 $('#comparison').innerHTML=`<div class="compare-scroll"><table><thead><tr><th scope="col">Details</th>${rows.map(r=>`<th scope="col">${photo(r)}<strong>${esc(r.name)}</strong><button data-compare="${r.id}" aria-label="Remove ${esc(r.name)} from comparison">Remove ×</button></th>`).join('')}</tr></thead><tbody>${columns.map(([name,fn])=>`<tr><th scope="row">${name}</th>${rows.map(r=>`<td>${fn(r)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p>Ratings may come from different providers and capture dates. Unknown values are not estimates.</p>`;imageFallbacks($('#comparison'));
}
function share(id){const r=restaurants.find(r=>r.id===id),u=new URL(location.href);u.search='';u.searchParams.set('place',id);$('#share-title').textContent='Share '+r.name;$('#share-url').value=u.href;$('#share-note').textContent=/^(localhost|127\.0\.0\.1)$/.test(location.hostname)?'This local preview link opens on this computer. A hosted version will make these same restaurant links shareable with others.':'This link opens this restaurant directly.';$('#share-dialog').showModal();}
function about(){const rows=restaurants;$('#data-stats').innerHTML=`<div class="stats"><span><b>${rows.length}</b>records</span><span><b>${rows.filter(r=>r.hours).length}</b>weekly hours</span><span><b>${rows.filter(r=>photos(r).length).length}</b>with photos</span></div><p>${rows.filter(r=>r.status==='closed').length} permanent closures, ${rows.filter(r=>r.status==='temporarily_closed').length} temporary closure, ${rows.filter(r=>r.status==='needs_review').length} needing review. Other listings are not all confirmed current.</p><p>${esc(bundle.communityData)} Latest targeted enrichment: ${esc(bundle.enrichmentAt||bundle.compiledAt)}.</p>`;$('#coverage-audit').innerHTML='<h3>Coverage by corridor</h3><table class="coverage-table"><tbody>'+Object.entries(bundle.audit?.districts||{}).map(([name,s])=>`<tr><th>${esc(name)}</th><td>${s.listed}</td></tr>`).join('')+'</tbody></table><p>Address-based navigation groups; counts include historical entries.</p>';$('#data-dialog').showModal();}
function download(){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({...bundle,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'}));a.download='nashua-restaurants-source-linked.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),5000);}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.open)showDetail(b.dataset.open);else if(b.dataset.save)save(b.dataset.save);else if(b.dataset.compare)compare(b.dataset.compare);else if(b.dataset.share)share(b.dataset.share);else if('cuisine'in b.dataset)applyFilter('cuisine',filters.cuisine===b.dataset.cuisine?'':b.dataset.cuisine);else if(b.dataset.quick)applyFilter('quick',filters.quick===b.dataset.quick?'':b.dataset.quick);else if('area'in b.dataset){applyFilter('district',b.dataset.area);if(!b.dataset.area&&!filterLabels().length)cityMap.fitCity();}else if(b.dataset.remove)applyFilter(b.dataset.remove,defaults()[b.dataset.remove]);else if('reset'in b.dataset)reset();else if(b.dataset.dish){closeDetail(false);filters=defaults();filters.query=b.dataset.dish;render({fly:true});}else if(b.dataset.close)$('#'+b.dataset.close).close();});
$('#search').addEventListener('input',e=>{filters.query=e.target.value;clearTimeout(searchTimer);if(/^best\b/i.test(filters.query))$('#sort').value='rating';searchTimer=setTimeout(()=>render({fly:true}),180);});$('#clear-search').onclick=()=>{clearTimeout(searchTimer);applyFilter('query','');};$('#reset').onclick=reset;$('#back-city').onclick=reset;
$('#local-area').onchange=e=>applyFilter('district',e.target.value);$('#price').onchange=e=>applyFilter('price',e.target.value);$('#rating').onchange=e=>applyFilter('rating',Number(e.target.value));$('#open-now').onchange=e=>applyFilter('open',e.target.checked);$('#include-closed').onchange=e=>applyFilter('includeClosed',e.target.checked);$('#sort').onchange=()=>render({updateMap:false});$('#favorites-filter').onclick=()=>applyFilter('favorites',!filters.favorites);$('#map-view').onclick=()=>setView('map');$('#list-view').onclick=()=>setView('list');$('#mobile-filters').onclick=()=>{setView('list');$('#filter-panel').open=true;$('#filter-panel summary').focus();};
$('#zoom-in').onclick=()=>cityMap.zoom(1);$('#zoom-out').onclick=()=>cityMap.zoom(-1);$('#north').onclick=()=>cityMap.north();$('#dimension').onclick=()=>cityMap.toggle3D();$('#home').onclick=()=>cityMap.fit(visible);$('#about').onclick=about;$('#download-data').onclick=download;$('#export').onclick=download;$('#compare-open').onclick=()=>{renderComparison();$('#compare-dialog').showModal();};$('#compare-clear').onclick=()=>{compareIds=[];render({updateMap:false});if(selected)renderDetail(restaurants.find(r=>r.id===selected));};$('#copy-link').onclick=async()=>{try{await navigator.clipboard.writeText($('#share-url').value);toast('Restaurant link copied');}catch{$('#share-url').select();toast('Select and copy the restaurant link above.');}};
$('#previous-place').onclick=()=>moveCarousel(-1);$('#next-place').onclick=()=>moveCarousel(1);$('#mobile-cards').onkeydown=e=>{if(['ArrowRight','ArrowLeft'].includes(e.key)){e.preventDefault();moveCarousel(e.key==='ArrowRight'?1:-1);}};$('#mobile-cards').onscroll=()=>{clearTimeout(carouselTimer);carouselTimer=setTimeout(()=>{const cards=$$('#mobile-cards .mobile-card');if(!cards.length)return;const left=$('#mobile-cards').getBoundingClientRect().left;const i=cards.reduce((best,c,i)=>Math.abs(c.getBoundingClientRect().left-left)<Math.abs(cards[best].getBoundingClientRect().left-left)?i:best,0);if(i!==carouselIndex){carouselIndex=i;cityMap.focus(visible[i],false);}updateCarouselCounter();},120);};
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$$('dialog[open]').length)closeDetail();if(e.key==='/'&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName)){e.preventDefault();$('#search').focus();}});window.addEventListener('popstate',()=>{const id=new URL(location.href).searchParams.get('place');if(id)showDetail(id);else closeDetail(false);});$('#legend').innerHTML=Object.entries(COLORS).map(([c,color])=>`<span><i style="--c:${color}"></i>${c==='Café & bakery'?'Cafés':c}</span>`).join('');
try{const response=await fetch('./data/restaurants.json');if(!response.ok)throw Error('Directory unavailable');bundle=await response.json();restaurants=bundle.restaurants;const ids=new Set(restaurants.map(r=>r.id));saved=new Set([...saved].filter(id=>ids.has(id)));$('#local-area').innerHTML='<option value="">Every neighborhood & corridor</option>'+Object.keys(bundle.audit.districts).map(name=>`<option value="${esc(name)}">${esc(name)}</option>`).join('');render();const deepId=new URL(location.href).searchParams.get('place');if(deepId){const r=restaurants.find(r=>r.id===deepId);if(r){filters.includeClosed=r.status==='closed';render();showDetail(deepId);cityMap.onReady=()=>cityMap.focus(r);}else toast('That restaurant link was not found.');}cityMap.init();document.body.dataset.appReady='true';}catch(error){$('#map-status').textContent='Restaurant data could not load. Reload to try again.';$('#results').innerHTML='<div class="empty">Directory unavailable.</div>';console.error(error);}
setInterval(()=>{if(!document.hidden&&bundle){const next=filterRows(restaurants,filters,saved);if(next.map(r=>r.id).sort().join()!==visible.map(r=>r.id).sort().join())render();else{for(const r of visible){const status=$(`#results [data-id="${r.id}"] .card-status`);if(status)status.textContent=statusText(r);}if(selected)renderDetail(restaurants.find(r=>r.id===selected));}}},60000);
